"""完整图纸提交给统一检查工具；最多三次模型调用，不运行模型程序。"""

import json

from langchain_core.messages import AIMessage, ToolMessage
from langchain_core.tools import tool

from app.design.facts import DesignFacts
from app.design.resolve_facts import COLLECTIONS, inspect_facts
from app.llm.client import create_llm
from app.llm.invocation import invoke_llm, stream_llm, merge_token_usage
from app.rag.trace import llm_trace_scope
from app.utils.json_extractor import extract_json_object


def _repair_issues(baseline, document):
    """修订保持实体和选定下限；需要布局取舍时仍由模型移动、调整设计。"""
    issues = []

    def keep(condition, path, message, actual, expected):
        if not condition:
            issues.append(
                {
                    "code": "repair_changed_constraint",
                    "paths": [path],
                    "entities": [],
                    "message": message,
                    "actual": actual,
                    "expected": expected,
                }
            )

    for name in COLLECTIONS:
        before = {row["id"] for row in baseline.get(name, [])}
        after = {row["id"] for row in document.get(name, [])}
        keep(
            before <= after,
            "/" + name,
            "修订不能删除或改名原实体以绕过错误",
            sorted(after),
            sorted(before),
        )
    keep(
        set(baseline["levels"]) <= set(document["levels"]),
        "/levels",
        "修订不能删除原有楼层引用",
        list(document["levels"]),
        list(baseline["levels"]),
    )
    before, after = DesignFacts.model_validate(baseline), DesignFacts.model_validate(
        document
    )
    for key, minimum in before.use_clearances.model_dump().items():
        actual = getattr(after.use_clearances, key)
        keep(
            actual >= minimum,
            "/use_clearances/" + key,
            "不能降低已选净距来消除错误",
            actual,
            minimum,
        )
    stairs = {s.id: s for s in after.stairs}
    for s in before.stairs:
        if s.id not in stairs:
            continue
        current = stairs[s.id]
        keep(
            current.max_riser_height <= s.max_riser_height,
            "/stairs",
            "不能放宽原楼梯步高上限",
            current.max_riser_height,
            {s.id: s.max_riser_height},
        )
        if s.steps_each is not None:
            keep(
                current.steps_each == s.steps_each,
                "/stairs",
                "保留原先明确指定的每跑级数",
                current.steps_each,
                {s.id: s.steps_each},
            )
    return issues


async def draft_design(
    *,
    base_prompt,
    user_request,
    diagnostics,
    current_plan=None,
    thinking_mode=False,
    on_reasoning_delta=None,
):
    context = (
        ("\n待修改的设计图纸：\n" + json.dumps(current_plan, ensure_ascii=False))
        if current_plan
        else ""
    )
    messages = [
        {"role": "system", "content": base_prompt},
        {"role": "user", "content": user_request + context},
    ]
    diagnostics.update(
        prompt=base_prompt,
        user_request=user_request,
        current_plan=current_plan,
        model_calls=0,
        rounds=[],
        token_usage=None,
        settled=False,
    )
    baseline = None

    @tool
    def inspect_design(design: dict) -> dict:
        """检查完整 DesignFacts 图纸并返回错误路径、实体、计算依据与检查范围。

        design 必须为完整图纸；不修改设计。通过的本次提交直接成为节点产物。
        """
        nonlocal baseline
        report = inspect_facts(design)
        if report["document"] is not None:
            if baseline is None:
                baseline = report["document"]
            report["issues"].extend(_repair_issues(baseline, report["document"]))
            report["valid"] = not report["issues"]
            report["coverage"]["checked"].append("修订保留实体和原选净距/步高约束")
        return report

    for attempt in range(1, 4):
        record = {"attempt": attempt}
        diagnostics["rounds"].append(record)
        diagnostics["model_calls"] += 1
        thinking = thinking_mode and attempt == 1
        try:
            llm = create_llm(
                enable_thinking=thinking,
                streaming=bool(thinking and on_reasoning_delta),
            )
            llm = llm.bind_tools([inspect_design])
            with llm_trace_scope(
                stage=(
                    "architecture.generate"
                    if attempt == 1
                    else "architecture.revise_facts"
                )
            ):
                if thinking and on_reasoning_delta:

                    async def emit(delta):
                        await on_reasoning_delta("architecture", delta)

                    reply = await stream_llm(llm, messages, on_reasoning_delta=emit)
                else:
                    reply = await invoke_llm(llm, messages, max_retries=0)
        except Exception:
            record["model_call_failed"] = True
            raise

        calls = [
            {
                "name": call["name"],
                "args": call["args"],
                "id": call.get("id") or f"inspection_{attempt}_{i}",
                "type": "tool_call",
            }
            for i, call in enumerate(reply.tool_calls)
        ]
        diagnostics["token_usage"] = merge_token_usage(
            diagnostics["token_usage"], reply.token_usage
        )
        record.update(
            output=reply.content,
            tool_calls=calls,
            invalid_tool_calls=reply.invalid_tool_calls,
            call_id=reply.call_id,
            finish_reason=reply.finish_reason,
            token_usage=reply.token_usage,
        )
        messages.append(AIMessage(content=reply.content or "", tool_calls=calls))
        candidate, issue = None, ""
        if reply.finish_reason == "length":
            issue = "模型输出达到长度上限，未接收为完整图纸"
        elif reply.invalid_tool_calls:
            issue = "工具调用参数未形成合法 JSON；请重新提交一个完整图纸"
        elif calls:
            if len(calls) == 1 and calls[0]["name"] == inspect_design.name:
                candidate = calls[0]["args"].get("design")
            else:
                issue = "每轮只提交一次 inspect_design(design=完整图纸)，不调用其他工具"
        else:
            candidate = extract_json_object(
                reply.content or "", required_key=("name", "levels", "volumes")
            )
        if not issue and not isinstance(candidate, dict):
            issue = "必须提交完整的设计事实 JSON 对象"
        if issue:
            report = {
                "valid": False,
                "issues": [
                    {
                        "code": "invalid_submission",
                        "paths": ["/"],
                        "entities": [],
                        "message": issue,
                    }
                ],
                "coverage": {"checked": [], "not_checked": ["图纸尚未成功解析"]},
            }
        else:
            # 即使直接返回 JSON 而未调用工具，也必须经过同一个检查入口。
            record["inspection_source"] = (
                "model_tool_call" if calls else "mandatory_gate"
            )
            report = inspect_design.invoke({"design": candidate})
        summary = {key: report[key] for key in ("valid", "issues", "coverage")}
        record["inspection"] = summary
        diagnostics["last_inspection"] = summary
        issue = "；".join(
            f"{','.join(row['paths'])}：{row['message']}" for row in report["issues"]
        )
        record["issue"] = diagnostics["last_issue"] = issue
        for call in calls:
            messages.append(
                ToolMessage(
                    content=json.dumps(summary, ensure_ascii=False),
                    tool_call_id=call["id"],
                )
            )
        if report["valid"]:
            diagnostics["settled"] = True
            return report
        if on_reasoning_delta:
            await on_reasoning_delta(
                "architecture:progress",
                f"图纸需要修订（{attempt}/3）：共 {len(report['issues'])} 项，{issue[:400]}。\n",
            )
        if reply.finish_reason == "length":
            break
        messages.append(
            {
                "role": "user",
                "content": "根据检查报告协调相关设计，再提交完整图纸。保留原需求、实体 ID 与已选净距/步高上限；"
                "调整位置、尺寸、宿主或路线，不得靠删除构件或降低标准绕过错误。"
                "复核尚未覆盖的设计关系，不要把工具通过当成全部设计正确。\n"
                + json.dumps(summary, ensure_ascii=False),
            }
        )
    return None

