"""设计事实的统一检查与确定性推导；不修改输入，不依赖某栋建筑的 ID。"""
from math import ceil, hypot

from pydantic import ValidationError

from .facts import DesignFacts

EPS = 1e-6
COLLECTIONS = ("volumes", "room_zones", "voids", "walls", "openings", "stairs", "roofs", "components", "routes")
UNCHECKED = [
    "房间功能与风格美感、所有房间完整可达性",
    "未明确关联的房间/门窗归属、入口台阶/门底关系",
    "构造配方、PBR、结构或消防实现",
    "L 形楼梯实际转向和到达板；本版只复核其参数与预留区",
    "楼梯全程净高、防护构造、路线宽度与非墙障碍物的完整碰撞",
]


def _inside(rect, outer):
    return (outer[0]-EPS <= rect[0] < rect[1] <= outer[1]+EPS
            and outer[2]-EPS <= rect[2] < rect[3] <= outer[3]+EPS)


def _slab_rectangles(regions, cuts):
    """矩形并集扣洞，再合并同行；同一算法也用于到达板支承检查。"""
    if not regions:
        return []
    xs = sorted({x for r in regions+cuts for x in r[:2]})
    zs = sorted({z for r in regions+cuts for z in r[2:]})
    result = []
    for z0, z1 in zip(zs, zs[1:]):
        row = []
        for x0, x1 in zip(xs, xs[1:]):
            cell = (x0, x1, z0, z1)
            if not any(_inside(cell, r) for r in regions) or any(_inside(cell, r) for r in cuts):
                continue
            if row and abs(row[-1][1]-x0) < EPS:
                row[-1][1] = x1
            else:
                row.append(list(cell))
        result.extend(row)
    return result


def _segment_in_rect(a, b, rect):
    """线段进入矩形内部的参数区间；仅沿边界行走不算穿入内部。"""
    low, high = 0.0, 1.0
    for axis, (start, end) in enumerate(((rect[0], rect[1]), (rect[2], rect[3]))):
        delta = b[axis]-a[axis]
        if abs(delta) < EPS:
            if not start+EPS < a[axis] < end-EPS:
                return None
        else:
            first, last = sorted(((start+EPS-a[axis])/delta, (end-EPS-a[axis])/delta))
            low, high = max(low, first), min(high, last)
            if high-low <= EPS:
                return None
    return (low, high) if high-low > EPS else None


def _wall_crossing(a, b, wall, width):
    """通路在墙中线占用的沿墙区间；包含斜穿和沿墙线重叠。"""
    c, d = wall["start"], wall["end"]
    rx, rz, sx, sz = b[0]-a[0], b[1]-a[1], d[0]-c[0], d[1]-c[1]
    length, travel = hypot(sx, sz), hypot(rx, rz)
    if length < EPS or travel < EPS:
        return None
    denominator = rx*sz-rz*sx
    qx, qz = c[0]-a[0], c[1]-a[1]
    if abs(denominator) < EPS:
        if abs(qx*rz-qz*rx) > EPS:
            return None
        along = [((p[0]-c[0])*sx+(p[1]-c[1])*sz)/length for p in (a, b)]
        low, high = max(0, min(along)), min(length, max(along))
        return (low, high) if high-low > EPS else None
    t, u = (qx*sz-qz*sx)/denominator, (qx*rz-qz*rx)/denominator
    if not -EPS <= t <= 1+EPS or not -EPS <= u <= 1+EPS:
        return None
    half = width/2 / (abs(denominator)/(length*travel))
    return (max(0,u*length-half), min(length,u*length+half))


def _covered(interval, intervals):
    if interval[1]-interval[0] <= EPS:
        return True
    end = interval[0]
    for low, high in sorted(intervals):
        if low > end+EPS:
            break
        end = max(end, high)
        if end >= interval[1]-EPS:
            return True
    return False


def _stair_geometry(stair, run, rise, exit_size):
    """固定方向约定下展开直梯/U 梯；返回上层到达板，不替模型换位置。"""
    x0, x1, z0, z1 = stair.rect
    origin, right, forward = {
        "+z": ((x0,z0),(1,0),(0,1)), "-z": ((x1,z1),(-1,0),(0,-1)),
        "+x": ((x0,z1),(0,-1),(1,0)), "-x": ((x1,z0),(0,1),(-1,0)),
    }[stair.direction]
    across = x1-x0 if stair.direction.endswith("z") else z1-z0

    def point(u, v):
        return [origin[0]+right[0]*u+forward[0]*v, origin[1]+right[1]*u+forward[1]*v]

    def rect(u0, u1, v0, v1):
        points = [point(u,v) for u in (u0,u1) for v in (v0,v1)]
        return [min(p[0] for p in points), max(p[0] for p in points),
                min(p[1] for p in points), max(p[1] for p in points)]

    if stair.shape == "straight":
        center = across/2
        return {"flights": [{"start": point(center,0), "end": point(center,run), "relative_rise": [0,rise]}],
                "void_rect": rect(0,across,0,run),
                "arrival_rect": rect(center-exit_size/2,center+exit_size/2,run,run+exit_size)}
    if stair.shape == "U":
        first, second = stair.flight_width/2, across-stair.flight_width/2
        return {"flights": [
                    {"start": point(first,0), "end": point(first,run), "relative_rise": [0,rise/2]},
                    {"start": point(second,run), "end": point(second,0), "relative_rise": [rise/2,rise]}],
                "landing_rect": rect(0,across,run,run+stair.landing_depth),
                "void_rect": list(stair.rect),
                "arrival_rect": rect(second-exit_size/2,second+exit_size/2,-exit_size,0)}
    return {"void_rect": list(stair.rect)}


class DesignInspectionError(ValueError):
    def __init__(self, report):
        self.report = report
        super().__init__("；".join(f"{','.join(row['paths'])}：{row['message']}" for row in report["issues"]))


def inspect_facts(value: DesignFacts | dict) -> dict:
    """模型工具与最终验收共用此入口；返回字段路径、实体和计算证据。"""
    issues, checked = [], []

    def check(condition, path, message, code="invalid_design", *, entities=(), actual=None, expected=None):
        if not condition:
            paths = [path] if isinstance(path, str) else path
            issue = {"code": code, "paths": ["/"+p for p in paths], "entities": list(entities), "message": message}
            if actual is not None:
                issue["actual"] = actual
            if expected is not None:
                issue["expected"] = expected
            issues.append(issue)

    def result(document=None, resolved=None):
        return {"valid": not issues, "issues": issues,
                "coverage": {"checked": checked, "not_checked": UNCHECKED},
                "document": document, "resolved": resolved}

    try:
        d = value if isinstance(value, DesignFacts) else DesignFacts.model_validate(value)
    except ValidationError as exc:
        for error in exc.errors(include_input=False, include_url=False):
            path = "/".join(map(str,error["loc"]))
            check(False, path, error["msg"].removeprefix("Value error, "), "schema_error")
        checked.append("字段与类型；因输入未形成图纸，依赖它的几何检查尚未执行")
        return result()
    checked.append("字段与类型")
    document = d.model_dump(mode="json", exclude_unset=True)
    document["units"] = "m"
    ordered = sorted(d.levels, key=d.levels.get)
    next_level = dict(zip(ordered, ordered[1:]))
    check(len(ordered) >= 2, "levels", "至少声明起始楼面与顶部板面", "level_order")
    check(len(set(d.levels.values())) == len(ordered), "levels", "不同楼层不能重复标高", "level_order")
    for low, high in zip(ordered, ordered[1:]):
        check(d.levels[high]-d.levels[low] > d.slab_thickness, "levels",
              "相邻标高差必须大于板厚", "level_order")

    ids, usable, missing_materials = set(), {}, {}
    for name in COLLECTIONS:
        usable[name] = []
        for i, row in enumerate(getattr(d,name)):
            path, refs_ok = f"{name}/{i}", True
            check(row.id not in ids, path+"/id", "实体 ID 必须全局唯一", "duplicate_id", entities=[row.id])
            ids.add(row.id)
            for field in ("level","bottom","top","from_level","to_level"):
                ref = getattr(row,field,None)
                if ref is not None and ref not in d.levels:
                    check(False,path+"/"+field,"楼层引用不存在","unknown_level",entities=[row.id],actual=ref)
                    refs_ok = False
            if refs_ok:
                usable[name].append((i,row))
            roles = [(role, path+"/material_roles/"+part.replace("~", "~0").replace("/", "~1"))
                     for part, role in row.material_roles.items()] if name == "components" else []
            if name in {"volumes","walls","stairs"} or name == "roofs" and row.type != "none":
                roles.append((row.material_role, path+"/material_role"))
            if name == "openings":
                roles.extend((getattr(row, field), path+"/"+field) for field in ("frame_role", "panel_role")
                             if getattr(row, field) is not None)
            for role, role_path in roles:
                if role not in d.material_roles:
                    group = missing_materials.setdefault(role, {"paths":[],"entities":[]})
                    group["paths"].append("/"+role_path)
                    if row.id not in group["entities"]:
                        group["entities"].append(row.id)
    # 材质缺失不妨碍尺寸检查；同一角色集中报告，避免逐墙刷屏再消耗一轮。
    for role, group in missing_materials.items():
        issues.append({"code":"unknown_material","message":"材质角色必须显式绑定本图已定义的材料",
                       **group,"actual":role,"expected":list(d.material_roles)})
    checked.append("全局 ID、楼层与材质引用")

    volumes = {v.id:v for _,v in usable["volumes"]}
    roofs = {r.volume:r for _,r in usable["roofs"]}
    for i, roof in usable["roofs"]:
        check(roof.volume in volumes,f"roofs/{i}/volume","屋面引用的体量不存在","unknown_volume",entities=[roof.id])
        check(sum(r.volume==roof.volume for r in d.roofs)==1,f"roofs/{i}",
              "一个体量只声明一份屋面","duplicate_roof",entities=[roof.id,roof.volume])
        check((roof.type in {"flat","none"} and roof.rise==0) or (roof.type not in {"flat","none"} and roof.rise>0),
              f"roofs/{i}/rise","坡屋面需要正起拱高度，flat/none 为 0",entities=[roof.id])
        check(not roof.walkable or roof.type=="flat",f"roofs/{i}/walkable",
              "本版仅支持平屋面作为露台",entities=[roof.id])
    for i,v in usable["volumes"]:
        check(d.levels[v.top]>d.levels[v.bottom],f"volumes/{i}","顶部必须高于起始楼面",entities=[v.id])
        check(v.id in roofs,f"volumes/{i}","明确声明屋面；敞开时 type=none",entities=[v.id])
        check(d.site is None or _inside(v.rect,d.site),f"volumes/{i}/rect","体量超出场地",entities=[v.id])
    for name in ("room_zones","voids","stairs"):
        for i,row in usable[name]:
            v = volumes.get(row.volume)
            check(v is not None,f"{name}/{i}/volume","引用的体量不存在","unknown_volume",entities=[row.id])
            if v is None:
                continue
            check(_inside(row.rect,v.rect),f"{name}/{i}/rect","占地超出引用体量","outside_volume",
                  entities=[row.id,v.id],actual=list(row.rect),expected=list(v.rect))
            refs = (row.from_level,row.to_level) if name=="stairs" else (row.level,)
            check(all(d.levels[v.bottom]<=d.levels[level]<=d.levels[v.top] for level in refs),
                  f"{name}/{i}","楼层超出引用体量",entities=[row.id])
            if name=="room_zones" and row.level==v.top:
                check(v.id in roofs and roofs[v.id].walkable,f"{name}/{i}/level",
                      "顶部房间需有可使用的平屋面",entities=[row.id])
    checked.append("体量、房间、挑空边界与屋面选择")

    wall_frames, boundaries = {}, {}
    for i,w in usable["walls"]:
        top = w.top or next_level.get(w.level)
        valid = top is not None and d.levels[top]-d.slab_thickness>d.levels[w.level] and w.start!=w.end
        check(valid,f"walls/{i}","墙段非零，且墙顶必须高于墙底","invalid_wall",entities=[w.id])
        if valid:
            wall_frames[w.id] = {"start":w.start,"end":w.end,"bottom":d.levels[w.level],
                "top":d.levels[top]-d.slab_thickness,"source_path":f"walls/{i}"}
    boundaries.update(wall_frames)
    for i,v in usable["volumes"]:
        x0,x1,z0,z1 = v.rect
        faces = {"front":((x0,z0),(x1,z0)),"back":((x1,z1),(x0,z1)),
                 "left":((x0,z1),(x0,z0)),"right":((x1,z0),(x1,z1))}
        for face,(a,b) in faces.items():
            boundaries[f"{v.id}:{face}"] = {"start":a,"end":b,"bottom":d.levels[v.bottom],
                "top":d.levels[v.top]-d.slab_thickness,"source_path":f"volumes/{i}"}

    opening_frames = []
    for i,o in usable["openings"]:
        path = f"openings/{i}"
        check((o.host in volumes and o.face is not None) or (o.host not in volumes and o.face is None),
              path+"/face","体量需要 face，独立墙段沿 start→end 定位","opening_face",entities=[o.id,o.host])
        key = f"{o.host}:{o.face}" if o.host in volumes else o.host
        frame = boundaries.get(key)
        check(frame is not None,path+"/host","宿主必须是真实体量墙面或独立墙段","unknown_host",entities=[o.id],actual=o.host)
        check(o.type=="opening" or o.frame_role is not None and o.panel_role is not None,
              path,"门窗需要明确框和扇的材质角色",entities=[o.id])
        check((o.type=="opening")==(o.style=="open"),path+"/style","通行洞口用 open，门窗选择 fixed/swing/slide",entities=[o.id])
        if frame is None:
            continue
        a,b = frame["start"],frame["end"]
        length = hypot(b[0]-a[0],b[1]-a[1])
        bottom = d.levels[o.level]+o.sill
        check(o.offset+o.width<=length+EPS,path+"/offset","开口超出宿主长度；核对宿主与位置","opening_outside_host",
              entities=[o.id,o.host],actual={"offset":o.offset,"width":o.width,"end":o.offset+o.width},
              expected={"host_length":length,"max_offset":length-o.width})
        check(frame["bottom"]-EPS<=bottom and bottom+o.height<=frame["top"]+EPS,path+"/height",
              "开口超出宿主墙高","opening_outside_host",entities=[o.id,o.host],
              actual=[bottom,bottom+o.height],expected=[frame["bottom"],frame["top"]])
        center = o.offset+o.width/2
        opening_frames.append({"id":o.id,"host":key,"type":o.type,"bottom":bottom,"top":bottom+o.height,
            "interval":[o.offset,o.offset+o.width],"source_path":path,
            "center_xz":[a[0]+(b[0]-a[0])*center/length,a[1]+(b[1]-a[1])*center/length]})
    for index,a in enumerate(opening_frames):
        for b in opening_frames[index+1:]:
            if a["host"]==b["host"] and min(a["top"],b["top"])>max(a["bottom"],b["bottom"])+EPS:
                overlap = min(a["interval"][1],b["interval"][1])-max(a["interval"][0],b["interval"][0])
                check(overlap<=EPS,[a["source_path"],b["source_path"]],"同一宿主上的开口重叠，需要协调两处开口","opening_overlap",
                      entities=[a["id"],b["id"]],actual={"host":a["host"],"intervals":[a["interval"],b["interval"]],"overlap":overlap})
    checked.append("真实门窗宿主、边界与同墙开口重叠")

    stairs,voids = [], [dict(v.model_dump(mode="json"),source_path=f"voids/{i}") for i,v in usable["voids"]]
    for i,s in usable["stairs"]:
        path = f"stairs/{i}"
        rise = d.levels[s.to_level]-d.levels[s.from_level]
        check(rise>0,path,"到达楼面必须高于起始楼面",entities=[s.id])
        if rise<=0 or s.volume not in volumes:
            continue
        flights = 1 if s.shape=="straight" else 2
        count = s.steps_each or ceil(rise/(flights*s.max_riser_height))
        riser,run = rise/(flights*count),count*s.tread_depth
        check(riser<=s.max_riser_height+EPS,path+"/steps_each","明确级数导致步高超限，不能放宽上限绕过","stair_riser",
              entities=[s.id],actual=riser,expected={"max_riser_height":s.max_riser_height})
        width,depth = s.rect[1]-s.rect[0],s.rect[3]-s.rect[2]
        along,across = (width,depth) if s.direction.endswith("x") else (depth,width)
        check(flights==1 or s.landing_depth>=s.flight_width,path+"/landing_depth","中间平台深度小于单跑宽度",entities=[s.id])
        required_along = run+s.landing_depth
        required_across = 2*s.flight_width if s.shape=="U" else required_along if s.shape=="L" else s.flight_width
        fits = along+EPS>=required_along and across+EPS>=required_across
        check(fits,path+"/rect","踏步、梯宽和平台无法放入预留区","stair_footprint",entities=[s.id],
              actual={"along":along,"across":across},expected={"along_min":required_along,"across_min":required_across})
        layout = _stair_geometry(s,run,rise,max(s.flight_width,d.use_clearances.upper_stair_exit_width))
        row = {"id":s.id,"rise":rise,"flights":flights,"steps_each":count,"riser_height":riser,
               "flight_run":run,"landing_elevation":None if flights==1 else (d.levels[s.from_level]+d.levels[s.to_level])/2,
               "to_level":s.to_level,"source_path":path,"geometry":layout}
        stairs.append(row)
        for level in ordered:
            if d.levels[s.from_level]<d.levels[level]<=d.levels[s.to_level]:
                voids.append({"id":f"stair:{s.id}:{level}","rect":layout["void_rect"],"level":level,"volume":s.volume,"source_path":path})
        collisions = [wid for wid,frame in boundaries.items()
            if frame["bottom"]<d.levels[s.to_level]-EPS and frame["top"]>d.levels[s.from_level]+EPS
            and _segment_in_rect(frame["start"],frame["end"],s.rect)]
        check(not collisions,path+"/rect","墙段穿入楼梯预留区；协调内墙、门洞和楼梯位置","wall_in_stair_space",
              entities=[s.id]+collisions,actual={"stair_rect":list(s.rect),"walls":collisions})
    checked.append("梯级、梯段/平台尺寸、自动梯井与墙段穿入预留区")

    slabs = {}
    for level in ordered:
        regions = [v.rect for v in volumes.values() if d.levels[v.bottom]<=d.levels[level]<=d.levels[v.top]
                   and not (level==v.top and (v.id not in roofs or roofs[v.id].type=="none"))]
        slabs[level] = {"top":d.levels[level],"bottom":d.levels[level]-d.slab_thickness,
                       "rectangles":_slab_rectangles(regions,[v["rect"] for v in voids if v["level"]==level])}
    for row in stairs:
        arrival = row["geometry"].get("arrival_rect")
        if arrival:
            uncovered = _slab_rectangles([arrival],slabs[row["to_level"]]["rectangles"])
            area = sum((r[1]-r[0])*(r[3]-r[2]) for r in uncovered)
            check(area<=EPS,row["source_path"]+"/rect","楼梯上层出口所需到达板没有完整楼面支承","stair_exit_support",
                  entities=[row["id"]],actual={"arrival_rect":arrival,"unsupported_area":area},
                  expected={"level":row["to_level"],"clear_size":d.use_clearances.upper_stair_exit_width})
    checked.append("楼板并集扣洞；直梯/U 梯上层到达板支承")

    for i,route in usable["routes"]:
        path = f"routes/{i}"
        check(all(a!=b for a,b in zip(route.points,route.points[1:])),path+"/points","相邻路径点不能相同",entities=[route.id])
        check(route.width>=d.use_clearances.main_routes_width,path+"/width","净宽低于本图自选的通路下限","route_width",
              entities=[route.id],actual=route.width,expected=d.use_clearances.main_routes_width)
        check(route.height>=d.use_clearances.route_headroom,path+"/height","净高低于本图自选的通路下限","route_height",
              entities=[route.id],actual=route.height,expected=d.use_clearances.route_headroom)
        bottom = d.levels[route.level]
        blocked,holes = {},set()
        for a,b in zip(route.points,route.points[1:]):
            for key,frame in boundaries.items():
                if frame["bottom"]>=bottom+route.height-EPS or frame["top"]<=bottom+EPS:
                    continue
                interval = _wall_crossing(a,b,frame,route.width)
                if interval is None:
                    continue
                allowed = [o["interval"] for o in opening_frames if o["host"]==key
                    and o["type"] in {"door","opening"} and o["bottom"]<=bottom+EPS and o["top"]>=bottom+route.height-EPS]
                if not _covered(interval,allowed):
                    blocked[key] = {"needed_interval":interval,"passable_intervals":allowed}
            for hole in voids:
                if hole["level"]==route.level and _segment_in_rect(a,b,hole["rect"]):
                    holes.add(hole["id"])
        check(not blocked,path+"/points","通路穿墙或沿墙线行走，现有门洞未覆盖所需净宽高","route_wall_conflict",
              entities=[route.id]+list(blocked),actual=blocked)
        check(not holes,path+"/points","本层平面路线穿过楼板空洞","route_over_void",
              entities=[route.id]+sorted(holes),actual=sorted(holes))
    checked.append("路线过墙净宽高、沿墙重叠与路线中心线穿过洞口")

    components = []
    for i,c in usable["components"]:
        check(c.repeat is None or c.repeat.count==1 or c.repeat.step!=(0,0),f"components/{i}/repeat",
              "多件阵列不能原地重叠",entities=[c.id])
        count,step = (c.repeat.count,c.repeat.step) if c.repeat else (1,(0,0))
        for n in range(count):
            dx,dz = step[0]*n,step[1]*n
            components.append({"id":c.id if count==1 else f"component:{c.id}:{n}","recipe":c.recipe,
                "bottom":d.levels[c.level]+c.elevation_offset-(c.height if c.anchor=="top" else 0),
                "rect":[c.rect[0]+dx,c.rect[1]+dx,c.rect[2]+dz,c.rect[3]+dz] if c.rect else None,
                "path":[[x+dx,z+dz] for x,z in c.path],"height":c.height,"rotation":c.rotation,
                "material_roles":dict(c.material_roles),"parameters":dict(c.parameters)})
    roof_frames = []
    for _,r in usable["roofs"]:
        if r.type=="none" or r.volume not in volumes:
            continue
        v = volumes[r.volume]
        x0,x1,z0,z1 = v.rect
        west,east,south,north = r.overhang
        roof_frames.append({"id":r.id,"rect":[x0-west,x1+east,z0-south,z1+north],
                            "support":d.levels[v.top]-d.slab_thickness,"slab_top":d.levels[v.top]})
    resolved = {"stairs":stairs,"voids":voids,"slabs":slabs,"walls":wall_frames,
                "components":components,"roofs":roof_frames,"openings":opening_frames,
                "scope":"设计关系的有界检查；不代表完整空间可达性、构造实现或渲染验收"}
    return result(document,resolved)


def resolve_facts(value: DesignFacts | dict) -> dict:
    """保留程序入口；和模型检查工具使用完全相同的判断。"""
    report = inspect_facts(value)
    if not report["valid"]:
        raise DesignInspectionError(report)
    return report["resolved"]
